verbraucherdarlehen_zinsschadensgrenze <- function(gesondert_verbuchte_verzugszinsen=NULL,nachgewiesener_zinsschaden=NULL,zeitanteil_zaehler=NULL,zeitanteil_nenner=NULL,zeitanteil_nachweis=NULL,einordnungsnachweis=NULL) {
 zinsschuld <- .geld(gesondert_verbuchte_verzugszinsen); schaden <- .geld(nachgewiesener_zinsschaden)
 .text(einordnungsnachweis,'einordnungsnachweis')
 deckel <- gesetzliche_zinsen(kapital=gesondert_verbuchte_verzugszinsen,zeitanteil_zaehler=zeitanteil_zaehler,zeitanteil_nenner=zeitanteil_nenner,zeitanteil_nachweis=zeitanteil_nachweis,glaeubigerverzug=FALSE,abweichender_zinssatz_prozent=NULL)
 grenze <- .geld(deckel$wert)
 eingaben <- list(gesondert_verbuchte_verzugszinsen=gesondert_verbuchte_verzugszinsen,nachgewiesener_zinsschaden=nachgewiesener_zinsschaden,zeitanteil_zaehler=zeitanteil_zaehler,zeitanteil_nenner=zeitanteil_nenner,zeitanteil_nachweis=zeitanteil_nachweis,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .geld_ergebnis(if(.vergleichen(schaden,grenze)<0) schaden else grenze,'BGB_VERBRAUCHERDARLEHEN_ZINSSCHADENSGRENZE',eingaben,list(list(operation='Vorhandenen gesetzlichen Vierprozent-Zinskern als Schadensobergrenze anwenden; nachgewiesenen Zinsschaden hierauf begrenzen.',gesetzlicher_hoechstbetrag=.bruchteile(grenze))))
 ergebnis$hinweise <- c(ergebnis$hinweise,list("Nur \u00a7497 Absatz2 Satz2 in Verbindung mit \u00a7289 Satz2 f\u00fcr Allgemein-Verbraucherdarlehen; Immobiliar-Verbraucherdarlehen nach Absatz4 ausgenommen. Grundlage sind qualifiziert gesondert verbuchte nach Verzugseintritt anfallende Zinsen, keine gesamte Darlehensrestschuld und kein automatischer Zinseszins. Ein einheitlicher Schadens-/Jahresanteilsabschnitt mit unver\u00e4nderter Zinsschuldbasis; bei laufend anfallenden Zinsen Teilabschnitte separat qualifizieren, keine Verzinsung vor Entstehung. Nachgewiesener Schaden und Anspruchsvoraussetzungen extern; der Vierprozentbetrag begrenzt nur den Schaden. Jahresanteil aus belegter Zeitkonvention, keine automatische365- oder360-Tage-Annahme."))
 ergebnis
}
